import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, vec3, vec4, uv } from 'three/tsl';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    TextureLoader,
  } = THREE;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const root = new Group();
  root.name = config.id ?? 'pricing-card-3';
  root.userData.handlers = {};

  const geometries = [];
  const materials = [];
  const textures = [];
  const primitiveResults = [];
  let disposed = false;

  const trackGeometry = (geometry) => {
    geometries.push(geometry);
    return geometry;
  };

  const trackMaterial = (material) => {
    materials.push(material);
    return material;
  };

  const makeGradientMaterial = () => {
    const material = trackMaterial(new MeshBasicNodeMaterial());
    const v = uv().y;
    material.colorNode = vec4(mix(vec3(surface), vec3(ink), v), 1);
    return material;
  };

  const backingGeometry = trackGeometry(new PlaneGeometry(3.05, 1.98));
  const backing = new Mesh(backingGeometry, makeGradientMaterial());
  backing.name = 'engineered-gradient-surface';
  backing.position.z = -0.08;
  root.add(backing);

  const imageGeometry = trackGeometry(new PlaneGeometry(2.88, 1.80));
  const imageMaterial = trackMaterial(new MeshBasicNodeMaterial({
    color: paper,
  }));
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.name = 'pricing-card-image';
  imagePlane.position.z = 0.02;
  root.add(imagePlane);

  const accentGeometry = trackGeometry(new PlaneGeometry(0.045, 1.54));
  const accentMaterial = trackMaterial(new MeshBasicNodeMaterial({
    color: accent,
  }));
  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.name = 'signal-red-edge';
  accentBar.position.set(-1.385, 0, 0.045);
  root.add(accentBar);

  const highlightGeometry = trackGeometry(new PlaneGeometry(2.58, 0.018));
  const highlightMaterial = trackMaterial(new MeshBasicNodeMaterial({
    color: paper,
    transparent: true,
    opacity: 0.34,
  }));
  const highlight = new Mesh(highlightGeometry, highlightMaterial);
  highlight.name = 'machined-highlight';
  highlight.position.set(0.05, 0.78, 0.05);
  root.add(highlight);

  const loadTexture = ctx.textureLoader?.loadTexture;
  if (config.imageUrl && loadTexture) {
    loadTexture.call(ctx.textureLoader, config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      textures.push(texture);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = THREE.ClampToEdgeWrapping;
      texture.wrapT = THREE.ClampToEdgeWrapping;
      texture.needsUpdate = true;

      imageMaterial.map = texture;
      imageMaterial.color.set(paper);
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply !== 'function') continue;

    const result = apply(root, primitive.params ?? {});
    if (result) primitiveResults.push(result);
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const result of primitiveResults) {
      result.timeline?.kill?.();
      result.cleanup?.();
    }

    for (const texture of textures) texture.dispose?.();
    for (const material of materials) material.dispose?.();
    for (const geometry of geometries) geometry.dispose?.();

    root.clear();
  };

  return root;
}

export default createNode;
